/* ── Alternate themes ──────────────────────────────────────────────────────────
   The base/light tokens above (`:root`) are the only ones shipped here. Every
   alternate theme lives in its own file under `css/themes/` (`dark.css`,
   `neon.css`, `finstat.css`) so a project links/bundles ONLY the ones it wants:

     <link rel="stylesheet" href="css/tokens.css" />          (required base)
     <link rel="stylesheet" href="css/themes/finstat.css" />  (opt-in)

   Then register the matching switcher entry in your shell bootstrap:
     import { registerThemes, BUILTIN_THEMES } from 'birko-web-shell';
     registerThemes([BUILTIN_THEMES.finstat]);

   To author a project-private theme, drop a `[data-theme="my-brand"]` block in
   your app's own CSS and `registerTheme({ id: 'my-brand', label: '…' })`. ── */

/* ── Reduced motion (accessibility) ───────────────────────────────────────────
   When the OS requests reduced motion, collapse all motion-token durations to a
   near-instant value so every component using --b-duration-* / --b-transition
   stops animating without each one needing its own media query. Light-DOM
   (page chrome) and host-level styles inherit these custom-property overrides
   through the Shadow DOM boundary, since inherited CSS variables cross it. */
@media (prefers-reduced-motion: reduce) {
  :root {
    --b-duration-instant: 0.01ms;
    --b-duration-fast: 0.01ms;
    --b-duration-base: 0.01ms;
    --b-duration-slow: 0.01ms;
    --b-transition: 0.01ms linear;
    --b-transition-slow: 0.01ms linear;
    --b-animation-speed: 0.01ms;
    --b-animation-slow: 0.01ms;
    --b-animation-progress: 0.01ms;
  }
}
